test('titres création : AST entier et français inchangés hors métadonnées de présentation',()=>{const p=path.join(root,'outils/audits/I18N-TITRES-CREATION-871-preuve.json'),proof=fs.existsSync(p)?JSON.parse(fs.readFileSync(p)):null,source=proof?execFileSync('git',['show',proof.codeCommit+':creation.js'],{cwd:root,encoding:'utf8'}):read('creation.js');assert.deepEqual(clean(parse(source)),clean(parse(old('creation.js'))));const ref=proof?.codeCommit||'HEAD';if(proof)assert.equal(execFileSync('git',['diff','--name-only',base,ref,'--','api','migrations','supabase','supabase.js','auth.js','data.js','plateau-core.js','style.css'],{cwd:root,encoding:'utf8'}),'');const ownIndex=proof?execFileSync('git',['show',proof.codeCommit+':index.html'],{cwd:root,encoding:'utf8'}):read('index.html');assert.equal(ownIndex.replace('creation.js?v=titres-personnage-871-','creation.js?v=').replace('connection-resources.js?v=titres-personnage-871-','connection-resources.js?v='),old('index.html'));});
test('titres création : six français exacts, neuf langues, catalogue antérieur intégralement conservé',()=>{const before=catalog(old('i18n/connection-resources.js')),after=catalog(read('i18n/connection-resources.js')),sources=JSON.parse(read('outils/audits/I18N-TITRES-CREATION-871-sources.json')).scope;assert.deepEqual(keys.map(k=>after.fr.translation.connectionUi[k]),sources);for(const lang of Object.keys(after)){const a=after[lang].translation.connectionUi,b=before[lang].translation.connectionUi;assert.deepEqual(Object.fromEntries(Object.keys(b).map(k=>[k,a[k]])),b);for(const key of keys){assert.ok(a[key].trim());assert.ok(!a[key].includes('{{'));if(lang!=='fr')assert.notEqual(a[key],after.fr.translation.connectionUi[key]);}assert.ok(Object.keys(a).length>=Object.keys(b).length+6);}});
